import { useMemo } from 'react';
import { CONTENTFUL_FALLBACK_LOCALE } from '../config/contentful';
import { useContentfulEntries } from './useContentful';
import { pickMostSpecificByRegion } from '../utils/resolveByRegion';
import type { SizeGuideEntry, SizeGuideTableEntry } from '../types/contentful';

// Narrow-guard used inside useMemo to filter out any sizeGuideTableReference items that
// resolveLinkedAssets could not resolve (e.g. unpublished entries absent from includes.Entry).
const isResolvedTableEntry = (t: unknown): t is SizeGuideTableEntry =>
  typeof t === 'object' && t !== null && 'fields' in t;

/**
 * Normalises an SFCC `c_sizeGuide` value to a Contentful entry key segment.
 *
 * SFCC stores size guide keys with a trailing numeric variant suffix and hyphens
 * (e.g. `"clothing-op-4"`). Contentful entry keys use underscores and no suffix
 * (e.g. `"clothing_op"`). This function strips the trailing `-{digits}` and
 * converts the remaining hyphens to underscores.
 */
export const normaliseKey = (key: string): string => key.replace(/-\d+$/, '').replace(/-/g, '_');

/**
 * Resolves a Contentful `sizeGuide` entry for the given SFCC `c_sizeGuide` key and locale,
 * with its `sizeGuideTableReference` links resolved to full `SizeGuideTableEntry` objects.
 *
 * Resolution order:
 * 1. `size-guide__{key}__{locale}` — locale-specific entry (locale = `{language}_{COUNTRY}`)
 * 2. `size-guide__{key}` — default fallback
 * 3. `null` — guide section hidden silently
 *
 * All fields are `localized: false`, so the Contentful fetch always uses
 * `CONTENTFUL_FALLBACK_LOCALE` to avoid unnecessary re-fetches on locale change.
 * The SFCC locale is used only for constructing the locale-specific key.
 *
 * `sizeGuideTableReference` Entry links are resolved inline by `resolveLinkedAssets` via
 * the `include=2` response — no separate sizeGuideTable collection fetch is needed.
 *
 * @returns The matched entry with resolved table references, or `null` when no match is found
 *   or `sizeGuideKey` is absent.
 */
export const useSizeGuide = (
  sizeGuideKey: string | undefined,
  locale: string,
  siteId: string,
): { sizeGuide: SizeGuideEntry | null; isLoading: boolean } => {
  // Compute candidate keys before the fetch so the filter can be passed to Contentful,
  // avoiding an unfiltered full-collection fetch.
  const normalisedKey = sizeGuideKey ? normaliseKey(sizeGuideKey) : undefined;
  // SFCC sends IETF locales with hyphens (e.g. 'en-AU'); Contentful entry keys and
  // locales[] use underscores ('en_AU') per the sizeGuide key regex and locales validation.
  const canonicalLocale = locale.replace('-', '_');
  const localeKey = normalisedKey ? `size-guide__${normalisedKey}__${canonicalLocale}` : undefined;
  const defaultKey = normalisedKey ? `size-guide__${normalisedKey}` : undefined;
  const keyFilter =
    localeKey && defaultKey
      ? `fields.key[in]=${encodeURIComponent(localeKey)},${encodeURIComponent(defaultKey)}&select=sys,fields`
      : undefined;

  // All sizeGuide fields are localized:false — fetch with fixed locale to avoid re-fetches.
  // Disabled when there is no key so products without a size guide skip the Contentful fetch.
  // sizeGuideTableReference Entry links are resolved inline via include=2 by resolveLinkedAssets.
  // include=3 required: sizeGuide → sizeGuideTable → imageFallback (image entry) → asset
  const { data: entries, isLoading } = useContentfulEntries<SizeGuideEntry>(
    'sizeGuide',
    false,
    CONTENTFUL_FALLBACK_LOCALE,
    keyFilter,
    Boolean(sizeGuideKey),
    3,
  );

  const sizeGuide = useMemo(() => {
    if (!sizeGuideKey || !entries || !localeKey || !defaultKey) return null;

    // For each candidate key group, pick the most region-specific entry eligible for
    // siteId. Guides with no regions (or empty regions) are global fallbacks; guides
    // with regions are valid only when a linked RegionEntry.fields.siteId matches.
    const localeMatches = entries.filter((e) => e.fields.key === localeKey);
    const defaultMatches = entries.filter((e) => e.fields.key === defaultKey);
    const matched =
      pickMostSpecificByRegion(localeMatches, siteId) ?? pickMostSpecificByRegion(defaultMatches, siteId) ?? null;

    if (!matched) return null;

    // Filter out unresolved links (entries absent from includes.Entry that resolveLinkedAssets
    // could not resolve — they have no `fields` property).
    const resolvedTables = (matched.fields.sizeGuideTableReference ?? []).filter(isResolvedTableEntry);

    return {
      ...matched,
      fields: {
        ...matched.fields,
        sizeGuideTableReference: resolvedTables,
      },
    };
  }, [entries, sizeGuideKey, localeKey, defaultKey, siteId]);

  return { sizeGuide, isLoading };
};

